import React, { useEffect, useState } from 'react';
import './style.css';

const SplashScreen = ({
  screenInterval,
  screenBg,
  screenIndex,
  contentHeight,
  contentWidth,
  contentBg,
  contentRadius,
  contentDirection,
  contentAlign,
  contentJustify,
  src,
  srcAlt,
  srcHeight,
  srcWidth,
  contentGap,
  screenBlur,
  contentBlur,
  contentShadow,
  animation,
  text,
  textColor,
  textSize,
  textWeight,
  textFont,
  cssScreen,
  cssContent,
  cssSrc,
  cssText
}) => {
  const [visible, setVisible] = useState(true);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setVisible(false);
    }, screenInterval);
    return () => {
      clearTimeout(timeoutId);
    };
  }, [screenInterval]);

  const onTransitionEnd = (event) => {
    if (event.propertyName !== 'opacity' || !event.target.classList.contains('fade-out')) return;
    setVisible(false);
  };

  return (
    <div
      className={cssScreen}
      style={{
        display: visible ? 'flex' : 'none',
        height: '100vh',
        width: '100vw',
        backgroundColor: screenBg,
        position: 'fixed',
        zIndex: screenIndex,
        backdropFilter: screenBlur
      }}
    >
      <div
        className={visible ? animation + ' ' + cssContent : 'fade-out'}
        onTransitionEnd={onTransitionEnd}
        style={{
          position: 'relative',
          height: contentHeight,
          width: contentWidth,
          backgroundColor: contentBg,
          borderRadius: contentRadius,
          display: 'flex',
          flexDirection: contentDirection,
          alignItems: contentAlign,
          justifyContent: contentJustify,
          gap: contentGap,
          margin: 'auto',
          backdropFilter: contentBlur,
          boxShadow: contentShadow
        }}
      >
        <img
          className={cssSrc}
          height={srcHeight}
          width={srcWidth}
          src={src}
          alt={srcAlt}
        />
        <p
          className={cssText}
          style={{
            color: textColor,
            fontSize: textSize,
            fontWeight: textWeight,
            fontFamily: textFont
          }}
        >
          {text}
        </p>
      </div>
    </div>
  );
};

SplashScreen.defaultProps = {
  screenInterval: 3000,
  screenBg: 'rgba(0, 0, 0, 0.5)',
  screenBlur: 'blur(5px)',
  screenIndex: 9999,
  contentHeight: '400px',
  contentWidth: '150px',
  contentBg: 'rgba(255, 255, 255, 0.9)',
  contentBlur: 'blur(3px)',
  contentShadow: '0px 0px 5px rgba(0, 0, 0, 0.3)',
  contentRadius: '9cvbvey',
  contentDirection: 'column',
  contentGap: '10px',
  contentAlign: 'center',
  contentJustify: 'center',
  src: 'https://cdn-icons-png.flaticon.com/512/5332/5332306.png',
  srcHeight: '30px',
  srcWidth: '30px',
  srcAlt: 'logo',
  animation: 'fade-in',
  text: 'Splash Screen',
  textColor: '#000',
  textSize: '10px',
  textWeight: 'bold',
  textFont: 'Arial',
  cssScreen: '',
  cssContent: '',
  cssSrc: '',
  cssText: ''
};

export default SplashScreen;

